INSERT INTO compact_core_guard SELECT IF(COUNT(*)=0,1,0) FROM (SELECT table_name,(index_name='PRIMARY') AS is_primary,GROUP_CONCAT(column_name ORDER BY seq_in_index) AS columns_in_key,SUM(sub_part IS NOT NULL) AS prefixes FROM information_schema.statistics WHERE table_schema='__SOURCE_SCHEMA__' AND table_name IN ('organization_department','employee','users','account_employee_binding','device_management','device_usage_record','device_capture_alert','model_management','detection_work_unit','detection_task','detection_work_unit_image','detection_quality_report','image_detection_data') AND non_unique=0 GROUP BY table_name,index_name) a LEFT JOIN compact_core_unique_keys e ON e.source_table=a.table_name AND e.is_primary=a.is_primary AND e.columns_in_key=a.columns_in_key WHERE e.source_table IS NULL OR a.prefixes<>0;
