INSERT INTO compact_core_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.`image_detection_data` s LEFT JOIN `historical_detection_summary` t ON t.`id`=s.`id` WHERE t.`id` IS NULL OR NOT(t.`id`<=>s.`id`) OR NOT(t.`model_id`<=>s.`model_id`) OR NOT(t.`detected_images_count`<=>s.`detected_images_count`) OR NOT(t.`normal_count`<=>s.`normal_count`) OR NOT(t.`bent_count`<=>s.`bent_count`) OR NOT(t.`deformed_count`<=>s.`deformed_count`) OR NOT(t.`rusty_count`<=>s.`rusty_count`) OR NOT(t.`missing_count`<=>s.`missing_count`) OR NOT(t.`compromised_count`<=>s.`compromised_count`) OR NOT(t.`miss_detection_rate`<=>s.`miss_detection_rate`) OR NOT(t.`start_time`<=>s.`start_time`) OR NOT(t.`finished_at`<=>s.`finished_at`) OR NOT(BINARY t.`folder_path`<=>BINARY s.`folder_path`) OR NOT(BINARY t.`result_path`<=>BINARY s.`result_path`) OR NOT(BINARY t.`annotated_images_path`<=>BINARY s.`annotated_images_path`) OR NOT(t.`detection_instances_count`<=>s.`detection_instances_count`);
INSERT INTO compact_core_guard SELECT IF((SELECT COUNT(*) FROM users WHERE binding_history_present=TRUE)=(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.account_employee_binding),1,0);
